"use client"

import * as React from "react"

import { cn } from "@/lib/utils"
import { roll } from "@/lib/0nlytype/roll"
import { rove } from "@/lib/0nlytype/rove"
import { Ring } from "@/components/ui/radial-chart"

type PieChartProps = Omit<React.ComponentProps<"figure">, "children"> & {
  /** One arc per entry, clockwise from the top in this order. */
  data: { label: string; value: number }[]
  /** Names the chart for assistive tech, e.g. "Where visits came from, September". */
  label: string
  /** What the values count. At rest the number reads "visits in all". */
  unit?: string
  format?: (value: number) => string
  /** ring: a whole ring, the total inside. horizon: a half ring standing on a horizon, the total on the line. */
  variant?: "ring" | "horizon"
  /** Pins the pointed-at look on one arc; set on the root for documentation. */
  "data-force"?: string
}

const figures = new Intl.NumberFormat("en-GB")
// The paper left between two arcs, as a share of the ring. ponytail: a fixed share, about 9px on a 22rem ring.
const GAP = 0.01
const place = (i: number) => String(i + 1).padStart(2, "0")

/**
 * Shares of a whole: one ring cut into arcs with a hairline of paper between them, numbered round the rim, and the
 * total as one very large number inside. Point at an arc, or focus its name, and it inks in the accent, the others
 * step back, and the total rolls down to that arc's share; leave and it rolls back up to the total.
 */
function PieChart({ data, label, unit, format = figures.format, variant = "ring", className, style, ...props }: PieChartProps) {
  const force = props["data-force"]?.split(" ").includes("hover")
  const [shown, setShown] = React.useState(force ? 0 : -1)
  const target = React.useRef(shown)
  const value = React.useRef<HTMLSpanElement>(null)
  const face = React.useRef<HTMLDivElement>(null)
  const key = React.useRef<HTMLUListElement>(null)

  const values = data.map((d) => (Number.isFinite(d.value) && d.value > 0 ? d.value : 0))
  const total = values.reduce((a, b) => a + b, 0)
  const shares = values.map((v) => (total > 0 ? v / total : 0))
  const starts = shares.map((_, i) => shares.slice(0, i).reduce((a, b) => a + b, 0))
  const many = shares.filter(Boolean).length > 1

  function show(i: number) {
    if (i === target.current || !value.current) return
    const was = target.current < 0 ? 1 : shares[target.current]
    const next = i < 0 ? 1 : shares[i]
    target.current = i
    roll(value.current, () => setShown(i), "0.3em", next > was ? 1 : -1)
  }
  const rest = () => !key.current?.contains(document.activeElement) && show(-1)

  // The arc under the pointer, read by its angle; off the ring (the middle included) the number rolls back to the total.
  function pick(e: React.PointerEvent) {
    const ring = face.current?.querySelector<HTMLElement>(".db-ring")
    if (!ring || total <= 0) return
    const box = ring.getBoundingClientRect()
    const r = box.width / 2
    const rtl = getComputedStyle(e.currentTarget).direction === "rtl"
    const dx = (e.clientX - box.left - r) * (rtl ? -1 : 1)
    const dy = e.clientY - box.top - r
    if (Math.abs(Math.hypot(dx, dy) - r) > 28) return rest()
    let t = (Math.atan2(dx, -dy) / (2 * Math.PI) + 1) % 1
    if (variant === "horizon") {
      t = ((t + 0.25) % 1) / 0.5
      if (t > 1) return rest()
    }
    const i = starts.findIndex((s, k) => shares[k] > 0 && t >= s && t < s + shares[k])
    if (i >= 0) show(i)
  }

  const at = shown >= 0 ? data[shown] : undefined
  const share = shown >= 0 ? shares[shown] * 100 : 0
  const percent = share > 0 && share < 1 ? "<1" : share.toFixed(share < 10 && share % 1 ? 1 : 0)
  const all = `${format(total)}${unit ? ` ${unit}` : ""}`

  return (
    <figure
      data-slot="pie-chart"
      data-variant={variant}
      data-pointed={shown >= 0 || undefined}
      aria-label={label}
      className={cn("db-pie", className)}
      style={{ "--n": data.length, ...style } as React.CSSProperties}
      {...props}
    >
      <div ref={face} data-slot="pie-chart-face" className="db-pie-face" aria-hidden="true" onPointerMove={pick} onPointerLeave={rest}>
        <div className="db-pie-arcs">
          {total > 0 ? (
            data.map((d, i) => {
              if (!shares[i]) return null
              // Each arc gives up the gap at both ends, but never more than half of itself.
              const len = many ? Math.max(shares[i] - GAP, shares[i] / 2) : 1
              return <Ring key={d.label} value={len} from={starts[i] + (shares[i] - len) / 2} head="none" data-shown={i === shown || undefined} />
            })
          ) : (
            <Ring value={0} head="none" data-empty="" />
          )}
        </div>
        {many
          ? data.map((d, i) =>
              shares[i] ? (
                <span key={d.label} className="db-pie-tick" data-shown={i === shown || undefined} style={{ "--t": starts[i] + shares[i] / 2 } as React.CSSProperties}>
                  {place(i)}
                </span>
              ) : null,
            )
          : null}
      </div>
      <figcaption data-slot="pie-chart-read" className="db-pie-read">
        <span ref={value} className="db-pie-value">
          {at ? (
            <>
              {percent}
              <span className="db-pie-unit">%</span>
            </>
          ) : (
            format(total)
          )}
        </span>
        <span className="db-pie-words">
          <span className="db-pie-name">{at ? at.label : unit ? `${unit} in all` : "In all"}</span>
          {/* At rest the line is held open, so the number doesn't move when an arc is pointed at. */}
          <span className="db-pie-of">{at ? `${format(values[shown])} of ${all}` : "\u00a0"}</span>
        </span>
      </figcaption>
      <ul
        ref={key}
        role="group"
        aria-label={label}
        data-slot="pie-chart-key"
        className="db-pie-key"
        onKeyDown={(e) => rove(e, "button", true)}
        onPointerLeave={rest}
        onBlur={(e) => !key.current?.contains(e.relatedTarget) && show(-1)}
      >
        {data.map((d, i) => (
          <li key={d.label}>
            <button
              type="button"
              tabIndex={i === Math.max(shown, 0) ? 0 : -1}
              data-shown={i === shown || undefined}
              onPointerEnter={() => show(i)}
              onFocus={() => show(i)}
            >
              <span className="db-pie-place" aria-hidden="true">{place(i)}</span>
              <span className="db-pie-key-name">{d.label}</span>
              <span className="db-pie-key-value">{format(values[i])}</span>
              <span className="db-sr">{`, ${Math.round(shares[i] * 100)}% of ${all}`}</span>
            </button>
          </li>
        ))}
      </ul>
    </figure>
  )
}

export { PieChart, type PieChartProps }

@layer components {
  /* ── db-pie ── shares of a whole, from the dot calendar's rings: radial-chart's ring cut into arcs, a hairline of
     paper between each, no wedges and no fills. The arcs are numbered round the rim, in the small print, and the total
     stands inside as one very large number. Point at an arc and it inks in the accent and swells, the others step back
     to pencil, and the total rolls down to that arc's share. */
  .db-pie {
    --db-pie-inset: var(--db-space-6);
    --dir: 1;
    margin: 0; display: grid; grid-template-columns: minmax(0, 1fr); inline-size: min(100%, var(--db-pie-size, 22rem)); row-gap: var(--db-space-5); container-type: inline-size;
  }
  .db-pie:is([dir="rtl"], [dir="rtl"] *) { --dir: -1; }
  .db-pie-face { grid-area: 1 / 1; position: relative; aspect-ratio: 1; container-type: inline-size; cursor: crosshair; }
  .db-pie-arcs { position: absolute; inset: 0; }
  .db-pie-arcs:is([dir="rtl"] *) { scale: -1 1; }

  /* The arcs are the whole ring: no track under them, so the gaps are paper. */
  .db-pie .db-ring { --db-ring-inset: var(--db-pie-inset); --db-ring-track: transparent; }
  .db-pie .db-ring[data-empty] { --db-ring-track: var(--db-rule-strong); }
  .db-pie .db-ring[data-shown] { --db-ring-ink: var(--db-accent); --db-stroke: calc(3 * var(--db-hairline)); }
  .db-pie:is([data-pointed], [data-force~="hover"]) .db-ring:not([data-shown]) { --db-ring-ink: var(--db-rule-strong); }

  /* The numbers round the rim, each at the middle of its arc, halfway into the margin the ring stands in. They stay
     upright: turned out to the arc, then back. */
  .db-pie-tick {
    position: absolute; top: 50%; left: 50%;
    transform: translate(-50%, -50%) rotate(calc(var(--dir) * (var(--db-ring-start, 0deg) + var(--t) * var(--db-ring-sweep, 1) * 1turn))) translateY(calc(var(--db-pie-inset) / 2 - 50cqi)) rotate(calc(-1 * var(--dir) * (var(--db-ring-start, 0deg) + var(--t) * var(--db-ring-sweep, 1) * 1turn)));
    font-size: var(--db-pp); line-height: 1; letter-spacing: var(--db-pp-tr); font-variant-numeric: tabular-nums lining-nums; color: var(--db-pencil);
    transition: color var(--db-allegro) var(--db-exhale);
  }
  .db-pie-tick[data-shown] { color: var(--db-ink); }

  /* The number stands in the middle, as large as the ring allows: SPECTRA's scale against the small print. */
  .db-pie-read {
    grid-area: 1 / 1; place-self: center; display: grid; justify-items: center; row-gap: var(--db-space-2);
    max-inline-size: calc(100% - 2 * var(--db-pie-inset) - var(--db-space-6)); text-align: center; pointer-events: none;
  }
  .db-pie-value {
    display: inline-block; font-size: clamp(var(--db-f), 22cqi, var(--db-fff)); line-height: 0.9; letter-spacing: var(--db-ff-tr); font-weight: 200;
    color: var(--db-ink); font-variant-numeric: tabular-nums lining-nums; white-space: nowrap;
  }
  .db-pie-unit { font-size: 0.4em; letter-spacing: 0; vertical-align: 0.95em; margin-inline-start: 0.08em; }
  .db-pie-words { display: grid; justify-items: center; font-size: var(--db-pp); line-height: var(--db-pp-lh); letter-spacing: var(--db-pp-tr); }
  .db-pie-name { font-weight: 500; color: var(--db-ink); }
  .db-pie-of { color: var(--db-pencil); font-variant-numeric: tabular-nums; }

  /* The key: a contents page of the arcs, number, name and figure on one line. One tab stop; the arrows walk it. */
  .db-pie-key { display: grid; grid-template-columns: auto minmax(0, 1fr) auto; column-gap: var(--db-space-4); margin: 0; padding: 0; list-style: none; }
  .db-pie-key > li { display: grid; grid-column: 1 / -1; grid-template-columns: subgrid; }
  .db-pie-key button {
    appearance: none; border: 0; margin: 0; padding: var(--db-space-1) 0; background: none; font: inherit; cursor: crosshair; text-align: start;
    display: grid; grid-column: 1 / -1; grid-template-columns: subgrid; align-items: baseline;
    font-size: var(--db-pp); line-height: var(--db-pp-lh); letter-spacing: var(--db-pp-tr); color: var(--db-pencil);
    transition: color var(--db-allegro) var(--db-exhale);
  }
  .db-pie-place, .db-pie-key-value { font-variant-numeric: tabular-nums lining-nums; }
  .db-pie-key-value { color: var(--db-graphite); transition: color var(--db-allegro) var(--db-exhale); }
  .db-pie-key button:is(:hover, :focus-visible, [data-shown]) { color: var(--db-ink); }
  .db-pie-key button:is(:hover, :focus-visible, [data-shown]) .db-pie-key-value { color: var(--db-ink); }

  /* horizon: the Eclipse. A half ring stands on a horizon that runs past it, and everything else is said below it:
     the number on the line (cap to baseline, so its feet stand on it), its words under the line. The rows keep no gap,
     or the subgrid would push the number half a gap below the line. Right to left, the arcs rise from the right. */
  .db-pie[data-variant="horizon"] { --db-ring-sweep: 0.5; --db-ring-start: -90deg; grid-template-rows: auto auto auto; row-gap: 0; }
  .db-pie[data-variant="horizon"] > .db-pie-face { aspect-ratio: 2; }
  .db-pie[data-variant="horizon"] .db-ring { inset-block-end: auto; aspect-ratio: 1; }
  .db-pie[data-variant="horizon"] .db-pie-tick { top: 100%; }
  .db-pie[data-variant="horizon"] > .db-pie-face::after { content: ""; position: absolute; inset-inline: 0; inset-block-end: 0; block-size: var(--db-hairline); background: var(--db-rule-strong); }
  .db-pie[data-variant="horizon"] > .db-pie-read { grid-row: 1 / span 2; place-self: stretch; grid-template-rows: subgrid; max-inline-size: none; row-gap: 0; }
  .db-pie[data-variant="horizon"] .db-pie-value { align-self: end; justify-self: center; font-size: clamp(var(--db-mf), 18cqi, var(--db-fff)); line-height: 1; text-box: trim-end cap alphabetic; }
  .db-pie[data-variant="horizon"] .db-pie-words { padding-block-start: var(--db-space-3); }
  .db-pie[data-variant="horizon"] > .db-pie-key { grid-row: 3; margin-block-start: var(--db-space-5); }

  @media (forced-colors: active) {
    .db-pie-tick { color: CanvasText; }
  }
}
